import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { pdppSafeText } from "@pdpp/connector-protocol/pdpp-safe-text";
import {
	decodeEscapedText,
	encodePdppSafeText,
	escapedLengthExceeds,
	isEscapedUnit,
} from "./safe-escape.ts";

// The vectors were generated by the ChatGPT connector's own codec
// (connectors/chatgpt/parsers.ts at tnunamak/pdpp-chatgpt-port-1015 @ed8bc4219),
// so a match here is a match with that reference, not with this module.
const fixture = JSON.parse(
	readFileSync(new URL("./safe-escape-vectors.json", import.meta.url), "utf8"),
) as {
	vectors: Array<{ raw: string; encoded: string }>;
	exceeds: Array<{ raw: string; cap: number; exceeds: boolean }>;
};

test("encode matches the ChatGPT reference vectors exactly", () => {
	assert.ok(fixture.vectors.length > 100);
	for (const { raw, encoded } of fixture.vectors)
		assert.equal(encodePdppSafeText(raw), encoded, JSON.stringify(raw));
});

test("decode restores every reference vector", () => {
	for (const { raw, encoded } of fixture.vectors)
		assert.equal(decodeEscapedText(encoded), raw, JSON.stringify(raw));
});

test("the length decision matches the ChatGPT reference vectors", () => {
	for (const { raw, cap, exceeds } of fixture.exceeds)
		assert.equal(
			escapedLengthExceeds(raw, cap).exceeds,
			exceeds,
			`${JSON.stringify(raw)} / ${cap}`,
		);
});

test("the escaped set is exactly C0/C1 controls except TAB LF CR, lone surrogates and backslash", () => {
	const escaped = [];
	for (let unit = 0; unit <= 0xff_ff; unit += 1)
		if (isEscapedUnit(unit)) escaped.push(unit);
	const expected = [];
	for (let unit = 0; unit <= 0xff_ff; unit += 1) {
		const control =
			(unit <= 0x1f && ![0x09, 0x0a, 0x0d].includes(unit)) ||
			(unit >= 0x7f && unit <= 0x9f);
		if (control || unit === 0x5c || (unit >= 0xd8_00 && unit <= 0xdf_ff))
			expected.push(unit);
	}
	assert.deepEqual(escaped, expected);
});

test("a backslash that would read as an escape is written \\u005C, other backslashes are unchanged", () => {
	assert.equal(encodePdppSafeText("\\u0001"), "\\u005Cu0001");
	assert.equal(encodePdppSafeText("\\u005c"), "\\u005Cu005c");
	assert.equal(encodePdppSafeText("\\u0041"), "\\u0041");
	assert.equal(encodePdppSafeText("C:\\dir\\file"), "C:\\dir\\file");
	assert.equal(encodePdppSafeText("\u0001"), "\\u0001");
	assert.equal(encodePdppSafeText("\u007f"), "\\u007F");
});

test("every code unit round-trips and its encoding is PDPP-safe text", () => {
	for (let unit = 0; unit <= 0xff_ff; unit += 1) {
		const raw = `a${String.fromCharCode(unit)}b`;
		const encoded = encodePdppSafeText(raw);
		assert.equal(decodeEscapedText(encoded), raw, `U+${unit.toString(16)}`);
		assert.equal(
			pdppSafeText.safeParse(encoded).success,
			true,
			`U+${unit.toString(16)} must encode to PDPP-safe text`,
		);
	}
});

test("seeded random mixes of controls, backslashes, escapes and surrogates round-trip", () => {
	let seed = 0x2f6e2b1;
	const next = () => {
		seed = (Math.imul(seed, 1_664_525) + 1_013_904_223) >>> 0;
		return seed;
	};
	const pieces = [
		"\\",
		"\\u",
		"\\u00",
		"\\u0001",
		"\\u005C",
		"\\u0041",
		"u",
		"0",
		"A",
		"\u0000",
		"\u0001",
		"\u001f",
		"\u007f",
		"\u0085",
		"\u009f",
		"\ud800",
		"\udc00",
		"😀",
		"é",
		"\t",
		"\n",
		" ",
	];
	for (let round = 0; round < 2000; round += 1) {
		let raw = "";
		const length = next() % 24;
		for (let i = 0; i < length; i += 1)
			raw += pieces[next() % pieces.length] ?? "";
		const encoded = encodePdppSafeText(raw);
		assert.equal(decodeEscapedText(encoded), raw, JSON.stringify(raw));
		assert.equal(pdppSafeText.safeParse(encoded).success, true);
	}
});
